/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountImageCompare, type ImageCompareOptions } from "../../components/image-compare/ImageCompareEngine.js";
import type { MotionController } from "../../components/image-compare/motion-runtime";

export function ImageCompare({ options, className }: { options?: ImageCompareOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountImageCompare(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="image-compare" />;
}

